-- Migration 131: Hilfetexte «Endschiessen Stiche lösen» nach der Critique vom 04.11.2026 (1.68.55):
-- Zahlung ohne Vorwahl, Aufschlüsselung des Betrags, Standblatt erst nach dem Speichern, «Nächste Person»,
-- Mitglieder mit Lösung bleiben in der Suche, Zeile anklicken, Tastenkürzel, Löschen nur ohne Resultate,
-- Bar/Karte in Kopf und Abrechnung, Preise gelten für alle Jahre (Mitglieder), Spezialpreise in einem Schritt.
-- Ersetzt die Texte aus 075/086/095 für diese Schlüssel; Ausgangslage war der Stand in der Datenbank.
--
-- Idempotent: ON DUPLICATE KEY UPDATE.
-- Hinweis: keine Zeile innerhalb der Strings darf mit zwei Bindestrichen beginnen (Kommentar-Filter des Runners).

INSERT INTO hilfetexte (schluessel, titel, inhalt_html, kategorie) VALUES

('endschloesen.uebersicht',
 'Endschiessen Stiche lösen',
 '<p>Hier wird erfasst, wer am Endschiessen welche Stiche löst und wie bezahlt wird. Oben stehen das Jahr, die Zahl der Teilnehmer mit der Summe des Jahres, die Einnahmen nach <strong>Bar</strong> und <strong>Karte</strong> (zum Zählen der Kasse und zum Abgleich mit dem Terminal) und die Knöpfe <strong>Abrechnung</strong> (PDF), Direktdruck und <strong>Definition</strong>. Darunter das Formular und die Übersicht aller Lösungen des gewählten Jahres (auf breiten Bildschirmen nebeneinander).</p><ul><li><strong>Ablauf</strong>: Person wählen, Waffe prüfen, Stiche anklicken, <strong>Bar oder Karte</strong> wählen (es ist nichts vorgewählt), <strong>Speichern</strong>. Danach bleibt die Person stehen und es erscheint «Gespeichert» mit Betrag und Zahlungsweg; jetzt das <strong>Standblatt</strong> herunterladen oder drucken. <strong>Nächste Person</strong> leert das Formular und öffnet die Suche.</li><li><strong>Standblatt</strong> gibt es nur für eine gespeicherte Lösung. So steht auf jedem Blatt, was auch in der Abrechnung steht. Nach einer Änderung zuerst wieder speichern.</li><li><strong>Gesamtbetrag</strong>: Darunter steht, woraus er sich zusammensetzt (Einzelstiche, Kombi-Preis, Sie und Er, Zusatzmunition). Verbindlich rechnet der Server beim Speichern.</li><li><strong>Waffe</strong> gilt für alle Stiche einer Person im Jahr. Bei Mitgliedern wird sie aus den Stammdaten vorbelegt, Gäste und Jungschützen starten mit Stgw 90. Die Stammdaten werden dabei nicht verändert. Die Zusatzmunition zeigt nur die zur Waffe passende Sorte.</li><li><strong>Fehlt etwas</strong> (Person, Waffe, Zahlungsweg), steht über den Knöpfen eine Liste; ein Klick springt ins Feld. Gespeichert wird erst, wenn alles stimmt.</li><li><strong>Übersicht</strong>: Zeile anklicken (oder mit den Pfeiltasten wählen und Enter) lädt die Lösung ins Formular. Das Menü «…» einer Zeile bietet Standblatt, Direktdruck und Löschen. In der Spalte <strong>Zahlung</strong> heisst «offen», dass für diese Lösung kein Zahlungsweg erfasst ist (ältere Einträge mit nur Munition): Zeile öffnen, Bar oder Karte wählen, speichern.</li><li><strong>Löschen</strong> fragt mit Jahr, Stichen und Betrag nach und sichert vorher die Datenbank. Wer im Jahr schon Resultate hat, behält die Lösung: zuerst unter «Endschiessen Resultate erfassen» die Resultate löschen. Bei Gästen und Jungschützen wird der Gast mit entfernt.</li><li><strong>Nicht gespeichert</strong> steht neben den Knöpfen, solange Änderungen offen sind. Vor dem Wechsel zu einer anderen Person, einem anderen Teilnehmertyp oder Jahr fragt die Seite: Speichern, Verwerfen oder Zurück.</li><li><strong>Tasten</strong>: Ctrl+S speichert, Ctrl+Enter speichert und geht zur nächsten Person.</li><li>Das Jahr gilt auch auf den anderen Seiten (für einige Stunden). Ist nicht das laufende Jahr gewählt, steht daneben «Archiv JAHR» mit einem Knopf zurück.</li></ul><p>Stich-Definitionen und Spezialpreise pflegen Admin und Vorstand über den Knopf <strong>«Definition»</strong> oben. Die <strong>Abrechnung</strong> (PDF) enthält am Schluss die Einnahmen nach Bar und Karte.</p>',
 'endschloesen'),

('endschloesen.teilnehmer',
 'Teilnehmertyp: Mitglied, Gast, Jungschütze',
 '<p>Der Umschalter bestimmt Preisregel und Speicherort:</p><ul><li><strong>Mitglied</strong>: in der Liste suchen. Wer im Jahr schon gelöst hat, ist mit «bereits gelöst» und dem Betrag markiert; Auswählen lädt die gespeicherte Lösung (z.B. um Munition nachzukaufen). Unter der Suche steht, wie viele Mitglieder (ohne Ausgetretene) noch nichts gelöst haben. Jeder Stich kostet seinen Einzelpreis, der Probestich ist gratis. Beim Zabig kann «Partner» angekreuzt werden, dann gilt der Partnerpreis.</li><li><strong>Gast</strong>: Name eingeben; ein bereits erfasster Gast wird erkannt und geladen. Sind im Formular schon Stiche angeklickt, wird nichts überschrieben: Der Hinweis unter dem Namen bietet «Gespeicherte Auswahl laden» an. Endstich und Schwini (Passe 1 und 2) kosten zusammen: ein Stich den Einzelpreis, zwei den Kombi-Preis 2, drei den Kombi-Preis 3; die Kacheln zeigen darum «in Kombi». «Sie und Er» kommt dazu, weitere Stiche (gestrichelte Kacheln) lassen sich zum Einzelpreis dazulösen; der Probestich ist für Gäste gesperrt. Ist eine Pauschale für «alle Stiche» gesetzt, gilt sie, sobald jeder Stich gewählt ist.</li><li><strong>Jungschütze/-in</strong>: Name und Geburtsdatum. Jungschützen lösen ein festes Paket (Endstich, Schwini Passe 1, Zabig, Probe) zum Jungschützen-Paketpreis. Ist das Paket gratis, braucht es keinen Zahlungsweg.</li></ul><p>Das Jahr oben neben dem Seitentitel steuert, für welches Endschiessen erfasst wird.</p>',
 'endschloesen'),

('endschloesen.stiche',
 'Stiche wählen',
 '<p>Jede Kachel ist ein Stich des Endschiessens mit Schusszahl und Preis. Angeklickte Stiche sind gelöst; «Alle» wählt alle Standard-Stiche des Teilnehmertyps, «Keine» leert die Auswahl.</p><ul><li>Welche Stiche für Gäste und Jungschützen wählbar sind, ist in den Regeln festgelegt; nicht zugelassene Kacheln sind ausgeblendet. Unter den Kacheln steht die Preisregel des Typs.</li><li>Der <strong>Gesamtbetrag</strong> unten ist eine Vorschau mit Aufschlüsselung; verbindlich rechnet der Server beim Speichern.</li><li><strong>Zusätzliche Munition</strong> (aufklappbar) wird zum Preis pro Schuss dazugerechnet. Angeboten wird die Sorte, die zur gewählten Waffe passt (Stgw 57, Karabiner: GP11; Stgw 90: GP90).</li></ul><p>Stiche, Preise und Reihenfolge der Kacheln stammen aus der Endschiessen-Definition (Knopf «Definition»). Sind keine aktiven Stiche definiert, steht hier ein Hinweis mit dem Weg zur Definition.</p>',
 'endschloesen'),

('endschloesen.definition',
 'Stich-Definitionen',
 '<p>Die Liste der Stiche des Endschiessens. Sie gilt jahresübergreifend und steuert die Kacheln im Formular, das Standblatt und die Abrechnung.</p><ul><li><strong>Code</strong> ist der technische Schlüssel (z.B. <code>END</code>, <code>ZABIG</code>, <code>PROBE</code>). Die Preisregeln für Gäste und Jungschützen hängen an diesen Codes; bestehende Codes deshalb nicht umbenennen.</li><li><strong>Name</strong>, <strong>Schuss</strong> und <strong>Preis</strong> erscheinen auf Kachel und Standblatt.</li><li><strong>Preis gilt für alle Jahre</strong>: Die Totale der Mitglieder werden aus dem aktuellen Preis gerechnet, auch für frühere Jahre (Übersicht und Abrechnung). Vor dem Speichern eines neuen Preises fragt die Seite deshalb nach. Gäste behalten den Preis, der beim Lösen galt.</li><li><strong>Sortierung</strong> ordnet die Kacheln. <strong>Aktiv</strong> ausschalten blendet einen Stich im Formular aus; wer ihn schon gelöst hat, behält ihn, auch wenn die Lösung später nochmals gespeichert wird.</li></ul><p>Schliessen mit offenen Änderungen fragt nach: Speichern, Verwerfen oder Zurück.</p>',
 'endschloesen'),

('endschloesen.spezialpreise',
 'Spezialpreise',
 '<p>Pauschalen, die statt der Einzelpreise gelten:</p><ul><li><strong>Munition pro Schuss</strong> (in Rappen): Preis der zusätzlichen Munition.</li><li><strong>Gäste: 2 Stiche</strong> und <strong>ab 3 Stiche</strong>: Preis für zwei bzw. drei Stiche aus Endstich und Schwini eines Gasts.</li><li><strong>Gäste: alle Stiche</strong>: Pauschale, wenn ein Gast jeden Stich löst; 0 schaltet sie aus.</li><li><strong>Gäste: Sie und Er</strong>: kommt zum Kombi-Preis dazu.</li><li><strong>Zabig mit Partner</strong>: Preis des Zabig, wenn ein Mitglied einen Partner angibt.</li><li><strong>Jungschützen-Paket</strong>: Preis des festen Pakets; 0 bedeutet gratis.</li></ul><p><strong>Spezialpreise speichern</strong> speichert alle Werte auf einmal (entweder alle oder keiner). Werte ausserhalb von 0 bis 1000 werden markiert und nicht gespeichert. Gäste behalten ihren beim Lösen gespeicherten Gesamtpreis, gekaufte Munition ihren gespeicherten Preis. Der Partner-Zabig der Mitglieder wird dagegen immer mit dem aktuellen Wert gerechnet, auch für frühere Jahre.</p>',
 'endschloesen')

ON DUPLICATE KEY UPDATE
    titel         = VALUES(titel),
    inhalt_html   = VALUES(inhalt_html),
    kategorie     = VALUES(kategorie),
    ist_geloescht = 0;
